-- Sessions and turns (contract K3).
--
-- A session is one recording from one device; its id is generated by the client
-- and is what makes an upload idempotent, so re-sending the same recording with
-- the same id rewrites the same rows instead of adding a second copy.
--
-- `turns.turn_index` is the position in ascending `start_ms` order, which is what
-- `turn_N` names. The document guard resolves a citation by
-- `(session_id, turn_index)`, so a turn can never be quoted from another
-- session's recording. Idempotent: safe to run on every start.

create table if not exists sessions (
    id text primary key,
    locale text not null check (locale in ('en', 'id')),
    audio_sha256 text not null,
    audio_bytes integer not null check (audio_bytes > 0),
    meta_session_id text,
    transcript text not null default '',
    audio_duration_ms integer check (audio_duration_ms is null or audio_duration_ms >= 0),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

create table if not exists turns (
    id bigserial primary key,
    session_id text not null references sessions (id) on delete cascade,
    turn_index integer not null check (turn_index >= 1),
    start_ms integer not null check (start_ms >= 0),
    end_ms integer not null check (end_ms >= start_ms),
    transcript text not null,
    final boolean not null default true,
    unique (session_id, turn_index)
);

create index if not exists turns_session_id_idx on turns (session_id);
